class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        ans = 0
        for i in range(n):
            cnt = [0] * 26
            distinct = bad = 0
            for j in range(i, n):
                if j > i and abs(ord(word[j]) - ord(word[j-1])) > 2:
                    break
                if j - i + 1 > 26 * k:
                    break
                c = ord(word[j]) - 97
                if cnt[c] == 0:
                    distinct += 1
                if cnt[c] == k:
                    bad += 1
                cnt[c] += 1
                L = j - i + 1
                if L % k == 0 and L // k == distinct and bad == 0:
                    ans += 1
        return ans

