class Solution {
public:
    long long countCompleteSubstrings(string word, int k) {
        int n = word.size();
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int cnt[26] = {0}, distinct = 0, bad = 0;
            for (int j = i; j < n; j++) {
                if (j > i && abs(word[j] - word[j-1]) > 2) break;
                if (j - i + 1 > 26 * k) break;
                int c = word[j] - 'a';
                if (cnt[c] == 0) distinct++;
                if (cnt[c] == k) bad++;
                cnt[c]++;
                int L = j - i + 1;
                if (L % k == 0 && L / k == distinct && bad == 0) ans++;
            }
        }
        return ans;
    }
};

