class Solution {
public:
    long long countCompleteSubstrings(string word, int k) {
        int n = word.size();
        long long ans = 0;
        int i = 0;
        while (i < n) {
            int j = i + 1;
            while (j < n && abs(word[j] - word[j-1]) <= 2) j++;
            int L = j - i;
            for (int m = 1; m <= min(26, L / k); m++) {
                int w = m * k, cnt[26] = {0}, good = 0;
                for (int idx = i; idx < j; idx++) {
                    int c = word[idx] - 'a';
                    if (cnt[c] == k) good--;
                    cnt[c]++;
                    if (cnt[c] == k) good++;
                    if (idx - i >= w) {
                        int d = word[idx - w] - 'a';
                        if (cnt[d] == k) good--;
                        cnt[d]--;
                        if (cnt[d] == k) good++;
                    }
                    if (idx - i >= w - 1 && good == m) ans++;
                }
            }
            i = j;
        }
        return ans;
    }
};

